import pandas as pdimport plotly.graph_objects as goimport plotly.io as piofrom plotly.colors import qualitativeimport numpy as npfrom scipy.stats import pearsonrfrom statsmodels.stats.multitest import multipletestsimport matplotlib.pyplot as pltimport seaborn as snsimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltimport seaborn as snsfrom matplotlib.colors import LinearSegmentedColormap, Normalizefrom matplotlib.lines import Line2Dfrom pathlib import Pathimport numpy as npimport matplotlib.pyplot as pltfrom matplotlib.axes import Axesfrom matplotlib.figure import Figurefrom matplotlib.ticker import MaxNLocatordef plot_y_distribution(    y,    y_train=None,    y_test=None,    *,    bins=20,    title=None,    xlabel="Response",    ylabel="Density",    show_std=False,    kde=True,    figsize=(5.8, 5.0),    full_color="lightgray",    train_color="steelblue",    test_color="tab:orange",    alpha=0.55,    edgecolor="black",    linewidth=0.5,    legend=True,    strip=True,    strip_height_ratio=0.26,    strip_size=3,    strip_alpha=0.75,    random_state=42,):    """    EDA plot with:    - histogram    - KDE    - horizontal strip plot at bottom    - horizontal boxplot overlaid on strip plot    Supports:    - full y only    - y_train vs y_test    Parameters    ----------    y : array-like        Full dataset values.    y_train : array-like or None, default=None        Training-set values.    y_test : array-like or None, default=None        Test-set values.    bins : int or sequence, default=20        Number of histogram bins or explicit bin edges.    title : str, default="Distribution of response variable"        Figure title.    xlabel : str, default="Response"        X-axis label.    ylabel : str, default="Density"        Y-axis label.    show_std : bool, default=False        If True, shade mean ± std of the full y distribution.    kde : bool, default=True        If True, overlay KDE curve(s).    figsize : tuple, default=(5.8, 5.0)        Figure size in inches.    full_color : str, default="lightgray"        Histogram color for full dataset.    train_color : str, default="steelblue"        Histogram color for training set.    test_color : str, default="tab:orange"        Histogram color for test set.    alpha : float, default=0.55        Histogram transparency.    edgecolor : str, default="black"        Histogram bar edge color.    linewidth : float, default=0.8        Histogram bar edge width.    legend : bool, default=True        Whether to show legend in train/test case.    strip : bool, default=True        If True, add bottom strip + boxplot panel.    strip_height_ratio : float, default=0.26        Relative height of lower panel.    strip_size : float, default=2.2        Marker size for strip points.    strip_alpha : float, default=0.75        Marker transparency.    random_state : int, default=42        Random seed for reproducible strip jitter.    Returns    -------    fig, (ax, ax_strip)    Usage    -----    fig, (ax, ax_strip) = edaplot(        y,        title="Dry matter distribution",        xlabel="Dry matter (%)",    )    plt.show()    fig, (ax, ax_strip) = edaplot(        y,        y_train=y_train,        y_test=y_test,        title="Train vs test dry matter distribution",        xlabel="Dry matter (%)",    )    plt.show()    """    import numpy as np    import matplotlib.pyplot as plt    import seaborn as sns    import matplotlib as mpl    from matplotlib.gridspec import GridSpec    # -------------------------    # Style    # -------------------------    mpl.rcParams.update({        "font.family": "Arial",        "font.size": 12,        "axes.labelsize": 12,        "axes.titlesize": 12,        "xtick.labelsize": 12,        "ytick.labelsize": 12,        "legend.fontsize": 12,        "svg.fonttype": "none",        "pdf.fonttype": 42,    })    rng = np.random.default_rng(random_state)    # -------------------------    # Prepare data    # -------------------------    y = np.asarray(y, dtype=float).ravel()    y = y[np.isfinite(y)]    if y.size == 0:        raise ValueError("y contains no finite values.")    has_split = (y_train is not None) or (y_test is not None)    if has_split:        if y_train is None or y_test is None:            raise ValueError("Provide both y_train and y_test, or neither.")        y_train = np.asarray(y_train, dtype=float).ravel()        y_test = np.asarray(y_test, dtype=float).ravel()        y_train = y_train[np.isfinite(y_train)]        y_test = y_test[np.isfinite(y_test)]        if y_train.size == 0:            raise ValueError("y_train contains no finite values.")        if y_test.size == 0:            raise ValueError("y_test contains no finite values.")    # -------------------------    # Shared bins    # -------------------------    if has_split:        all_vals = np.concatenate([y_train, y_test])    else:        all_vals = y    if np.isscalar(bins):        bin_edges = np.histogram_bin_edges(all_vals, bins=bins)    else:        bin_edges = np.asarray(bins)    # -------------------------    # Figure and axes    # -------------------------    if strip:        fig = plt.figure(figsize=figsize)        gs = GridSpec(            2, 1,            height_ratios=[1 - strip_height_ratio, strip_height_ratio],            hspace=0.03,            figure=fig,        )        ax = fig.add_subplot(gs[0])        ax_strip = fig.add_subplot(gs[1], sharex=ax)    else:        fig, ax = plt.subplots(figsize=figsize)        ax_strip = None    # -------------------------    # Main histogram panel    # -------------------------    if not has_split:        sns.histplot(            y,            bins=bin_edges,            stat="density",            color=full_color,            edgecolor=edgecolor,            linewidth=linewidth,            alpha=0.85,            ax=ax,        )        if kde and y.size > 1:            sns.kdeplot(                y,                color="black",                linewidth=1.8,                ax=ax,                clip=(bin_edges[0], bin_edges[-1]),            )    else:        sns.histplot(            y_train,            bins=bin_edges,            stat="density",            color=train_color,            alpha=alpha,            edgecolor=edgecolor,            linewidth=linewidth,            ax=ax,            label="Train",        )        sns.histplot(            y_test,            bins=bin_edges,            stat="density",            color=test_color,            alpha=alpha,            edgecolor=edgecolor,            linewidth=linewidth,            ax=ax,            label="Test",        )        if kde:            if y_train.size > 1:                sns.kdeplot(                    y_train,                    color=train_color,                    linewidth=1.8,                    ax=ax,                    clip=(bin_edges[0], bin_edges[-1]),                )            if y_test.size > 1:                sns.kdeplot(                    y_test,                    color=test_color,                    linewidth=1.8,                    ax=ax,                    clip=(bin_edges[0], bin_edges[-1]),                )        if legend:            ax.legend(frameon=False)    # -------------------------    # Optional std shading    # -------------------------    if show_std:        mean_val = np.mean(y)        std_val = np.std(y, ddof=1) if y.size > 1 else 0.0        ax.axvspan(            mean_val - std_val,            mean_val + std_val,            color="0.5",            alpha=0.08,            zorder=0,        )    # -------------------------    # Main axis styling    # -------------------------    ax.set_ylabel(ylabel)    if title is not None:        ax.set_title(title)    ax.grid(True, linestyle=":", linewidth=0.7, alpha=0.35)    ax.spines["top"].set_visible(False)    ax.spines["right"].set_visible(False)    ax.spines["left"].set_linewidth(0.9)    ax.spines["bottom"].set_linewidth(0.9)    if strip:        plt.setp(ax.get_xticklabels(), visible=False)        ax.set_xlabel("")    else:        ax.set_xlabel(xlabel)    # -------------------------    # Bottom panel: boxplot + strip    # -------------------------    if strip and ax_strip is not None:        if not has_split:            # Boxplot            ax_strip.boxplot(                y,                vert=False,                positions=[1],                widths=0.45,                patch_artist=True,                boxprops=dict(facecolor="white", edgecolor="black", linewidth=1),                medianprops=dict(color="black", linewidth=1),                whiskerprops=dict(color="black", linewidth=1),                capprops=dict(color="black", linewidth=1),                flierprops=dict(                    marker="o",                    markersize=4,                    markerfacecolor="none",                    markeredgecolor="black",                    linestyle="none",                ),            )            # Strip points            y_jitter = rng.uniform(-0.14, 0.14, size=y.size) + 1.0            ax_strip.scatter(                y,                y_jitter,                s=strip_size**2,                color="grey",                alpha=strip_alpha,                linewidth=0,                zorder=3,            )            ax_strip.set_yticks([1])            ax_strip.set_yticklabels([f"(n={len(y)})"])              ax_strip.set_ylim(0.6, 1.4)        else:            # TRAIN first, TEST second            bp = ax_strip.boxplot(                [y_train, y_test],                vert=False,                positions=[1, 2],                widths=0.45,                patch_artist=True,                boxprops=dict(facecolor="white", edgecolor="black", linewidth=1),                medianprops=dict(color="black", linewidth=1),                whiskerprops=dict(color="black", linewidth=1),                capprops=dict(color="black", linewidth=1),                flierprops=dict(                    marker="o",                    markersize=4,                    markerfacecolor="none",                    markeredgecolor="black",                    linestyle="none",                ),            )            # Keep white fill or set colors here if wanted            bp["boxes"][0].set_facecolor("white")  # Train            bp["boxes"][1].set_facecolor("white")  # Test            # Strip points aligned to same order            y_train_jitter = rng.uniform(-0.14, 0.14, size=y_train.size) + 1.0            y_test_jitter = rng.uniform(-0.14, 0.14, size=y_test.size) + 2.0            ax_strip.scatter(                y_train,                y_train_jitter,                s=strip_size**2,                color=train_color,                alpha=strip_alpha,                linewidth=0,                zorder=3,            )            ax_strip.scatter(                y_test,                y_test_jitter,                s=strip_size**2,                color=test_color,                alpha=strip_alpha,                linewidth=0,                zorder=3,            )            # Match visual order with legend            ax_strip.set_yticks([1, 2])            ax_strip.set_yticklabels([            f"(n={len(y_train)})",            f"(n={len(y_test)})"             ])            ax_strip.set_ylim(0.5, 2.5)            ax_strip.invert_yaxis()  # puts Train on top, Test below        ax_strip.set_xlabel(xlabel)        ax_strip.grid(False)        ax_strip.spines["top"].set_visible(False)        ax_strip.spines["right"].set_visible(False)        ax_strip.spines["left"].set_visible(False)        ax_strip.spines["bottom"].set_linewidth(0.9)    fig.subplots_adjust(hspace=0.05)    return fig, (ax, ax_strip)def plot_nmr_interactive(    df,    metadata=None,    color_by=None,    color_map=None,    title="NMR spectra",    x_label="Chemical shift (ppm)",    y_label="Intensity",    reverse_x=True,    renderer="browser",    line_width=1,    opacity=1,    max_samples=None,    ppm_range=None,    downsample=1,    show_legend=True,    width=2500,    height=1100,):    """    Plot NMR spectra interactively using Plotly.    Parameters    ----------    df : pandas.DataFrame        NMR spectral data:        rows = samples        columns = chemical-shift values in ppm.    metadata : pandas.DataFrame, optional        Sample metadata. Its index must contain the sample IDs in `df`.    color_by : str, optional        Metadata column used to color the spectra.        For example, color_by="sample_type".        If None, spectra are colored individually.    color_map : dict, optional        Custom mapping between group names and colors.        Example:        {            "bread": "#1f77b4",            "cake": "#ff7f0e",            "wafer": "#2ca02c",        }    title : str, default="NMR spectra"        Plot title.    x_label : str, default="Chemical shift (ppm)"        X-axis label.    y_label : str, default="Intensity"        Y-axis label.    reverse_x : bool, default=True        Reverse the x-axis, as conventionally used for NMR spectra.    renderer : str or None, default="browser"        Plotly renderer. Use "browser" when working in Spyder.        If None, the current Plotly renderer is not changed.    line_width : float, default=1        Width of spectral lines.    opacity : float, default=1        Line opacity between 0 and 1.    max_samples : int, optional        Plot only the first N samples.    ppm_range : tuple, optional        Chemical-shift region to retain.        Example:        ppm_range=(10, -1)    downsample : int, default=1        Plot every nth spectral point.        Example:        downsample=5    show_legend : bool, default=True        Show or hide the legend.    width : int, default=2500        Figure width in pixels.    height : int, default=1100        Figure height in pixels.    Returns    -------    plotly.graph_objects.Figure        Interactive Plotly figure.    Usage:                Version 1                f.plotting.plot_nmr_interactive(df_nmr80).show()                Version 2                sample_type_colors = {        "bread": "#1f77b4",        "cake": "#d62728",        "wafer": "#2ca02c",        "Unknown": "#7f7f7f",    }        fig = plot_nmr_interactive(        df,        metadata=df_meta,        color_by="sample_type",        color_map=sample_type_colors,    )fig.show()    """    # -------------------------------------------------------------------------    # Validate inputs    # -------------------------------------------------------------------------    if not isinstance(df, pd.DataFrame):        raise TypeError("df must be a pandas DataFrame.")    if df.empty:        raise ValueError("df is empty.")    if not isinstance(downsample, int) or downsample < 1:        raise ValueError("downsample must be an integer greater than or equal to 1.")    if max_samples is not None:        if not isinstance(max_samples, int) or max_samples < 1:            raise ValueError("max_samples must be a positive integer or None.")    if not 0 <= opacity <= 1:        raise ValueError("opacity must be between 0 and 1.")    # -------------------------------------------------------------------------    # Prepare spectral data    # -------------------------------------------------------------------------    df_plot = df.copy()    try:        df_plot.columns = df_plot.columns.astype(float)    except (TypeError, ValueError) as error:        raise ValueError(            "All columns of df must represent numeric chemical-shift values."        ) from error    # Sort chemical shifts from high to low    df_plot = df_plot.sort_index(axis=1, ascending=False)    # Select chemical-shift range    if ppm_range is not None:        if len(ppm_range) != 2:            raise ValueError("ppm_range must contain exactly two values.")        high_ppm = max(ppm_range)        low_ppm = min(ppm_range)        mask = (            (df_plot.columns >= low_ppm)            & (df_plot.columns <= high_ppm)        )        df_plot = df_plot.loc[:, mask]        if df_plot.shape[1] == 0:            raise ValueError(                "No chemical-shift values were found inside ppm_range."            )    # Select samples    if max_samples is not None:        df_plot = df_plot.iloc[:max_samples]    # Reduce number of plotted points    df_plot = df_plot.iloc[:, ::downsample]    # -------------------------------------------------------------------------    # Prepare grouping information    # -------------------------------------------------------------------------    group_values = None    if color_by is not None:        if metadata is None:            raise ValueError(                "metadata must be provided when color_by is used."            )        if not isinstance(metadata, pd.DataFrame):            raise TypeError("metadata must be a pandas DataFrame.")        if color_by not in metadata.columns:            raise KeyError(                f"'{color_by}' was not found in metadata. "                f"Available columns: {list(metadata.columns)}"            )        missing_samples = df_plot.index.difference(metadata.index)        if len(missing_samples) > 0:            raise ValueError(                "The following samples are missing from metadata: "                f"{missing_samples.tolist()}"            )        group_values = (            metadata.loc[df_plot.index, color_by]            .fillna("Unknown")            .astype(str)        )        groups = list(pd.unique(group_values))        # Create automatic color map        if color_map is None:            available_colors = (                qualitative.Plotly                + qualitative.Safe                + qualitative.Dark24            )            color_map = {                group: available_colors[i % len(available_colors)]                for i, group in enumerate(groups)            }        # Check custom color map        else:            missing_colors = [                group for group in groups                if group not in color_map            ]            if missing_colors:                raise ValueError(                    "color_map does not contain colors for: "                    f"{missing_colors}"                )    # -------------------------------------------------------------------------    # Create interactive plot    # -------------------------------------------------------------------------    if renderer is not None:        pio.renderers.default = renderer    fig = go.Figure()    groups_added_to_legend = set()    for sample_id in df_plot.index:        if color_by is None:            trace_name = str(sample_id)            legend_group = str(sample_id)            trace_color = None            display_in_legend = show_legend            customdata = None            hovertemplate = (                "Sample: %{fullData.name}<br>"                "ppm: %{x:.4f}<br>"                "Intensity: %{y:.3g}"                "<extra></extra>"            )        else:            group = group_values.loc[sample_id]            trace_name = group            legend_group = group            trace_color = color_map[group]            # Show each group only once in the legend            display_in_legend = (                show_legend                and group not in groups_added_to_legend            )            groups_added_to_legend.add(group)            customdata = [str(sample_id)] * df_plot.shape[1]            hovertemplate = (                "Sample: %{customdata}<br>"                f"{color_by}: {group}<br>"                "ppm: %{x:.4f}<br>"                "Intensity: %{y:.3g}"                "<extra></extra>"            )        fig.add_trace(            go.Scatter(                x=df_plot.columns,                y=df_plot.loc[sample_id].to_numpy(),                mode="lines",                name=trace_name,                legendgroup=legend_group,                showlegend=display_in_legend,                customdata=customdata,                line={                    "width": line_width,                    "color": trace_color,                },                opacity=opacity,                hovertemplate=hovertemplate,            )        )    # -------------------------------------------------------------------------    # Format figure    # -------------------------------------------------------------------------    legend_title = color_by if color_by is not None else "Sample ID"    fig.update_layout(        title={            "text": title,            "x": 0.5,            "xanchor": "center",        },        xaxis_title=x_label,        yaxis_title=y_label,        template="simple_white",        hovermode="closest",        showlegend=show_legend,        legend_title_text=legend_title,        legend={            "groupclick": "togglegroup",        },        width=width,        height=height,        font={            "family": "Arial",            "size": 16,        },    )    fig.update_xaxes(        showline=True,        linewidth=1,        linecolor="black",        mirror=True,        ticks="outside",        autorange="reversed" if reverse_x else True,    )    fig.update_yaxes(        showline=True,        linewidth=1,        linecolor="black",        mirror=True,        ticks="outside",    )    return figdef plot_ftir_interactive(    df,    metadata=None,    color_by=None,    color_map=None,    title="FTIR spectra",    x_label="Wavenumber (cm⁻¹)",    y_label="Absorbance",    reverse_x=True,    renderer="browser",    line_width=1,    opacity=1,    max_samples=None,    wavenumber_range=None,    downsample=1,    show_legend=True,):    """    Plot FTIR spectra interactively.    Parameters    ----------    df : pandas.DataFrame        FTIR spectra with samples in rows and wavenumbers        in columns.    metadata : pandas.DataFrame, optional        Sample metadata. The index must match the sample IDs in `df`.    color_by : str, optional        Metadata column used to color the spectra.        For example, color_by="sample_type".    color_map : dict, optional        Custom mapping between group names and colors.    title : str, default="FTIR spectra"        Figure title.    x_label : str, default="Wavenumber (cm⁻¹)"        X-axis label.    y_label : str, default="Absorbance"        Y-axis label.    reverse_x : bool, default=True        Display high wavenumbers on the left.    renderer : str or None, default="browser"        Plotly renderer. Use "browser" when working in Spyder.    line_width : float, default=1        Width of spectral lines.    opacity : float, default=1        Line opacity between 0 and 1.    max_samples : int, optional        Plot only the first N samples.    wavenumber_range : tuple, optional        Wavenumber region to display.        Example:        wavenumber_range=(4000, 600)    downsample : int, default=1        Plot every nth spectral point.    show_legend : bool, default=True        Show or hide the legend.    Returns    -------    plotly.graph_objects.Figure        Interactive FTIR figure.    Notes    -----    The input data are assumed to be cleaned and standardized.    This function does not modify the original DataFrame.    Usage    -----    Plot all spectra:    >>> fig = plot_ftir_interactive(df_ftir)    >>> fig.show()    Color spectra by sample type:    >>> fig = plot_ftir_interactive(    ...     df_ftir,    ...     metadata=df_meta,    ...     color_by="sample_type",    ... )    >>> fig.show()    """    df_plot = df.copy()    # Convert the spectral axis to numeric values    df_plot.columns = df_plot.columns.astype(float)    # Select a wavenumber region    if wavenumber_range is not None:        low, high = sorted(wavenumber_range)        mask = (            (df_plot.columns >= low)            & (df_plot.columns <= high)        )        df_plot = df_plot.loc[:, mask]        if df_plot.shape[1] == 0:            raise ValueError(                "No columns were found inside wavenumber_range."            )    # Select a limited number of samples    if max_samples is not None:        df_plot = df_plot.iloc[:max_samples]    # Reduce the number of plotted points    if downsample > 1:        df_plot = df_plot.iloc[:, ::downsample]    if renderer is not None:        pio.renderers.default = renderer    fig = go.Figure()    # ------------------------------------------------------------------    # Plot without metadata grouping    # ------------------------------------------------------------------    if color_by is None:        for sample_id in df_plot.index:            fig.add_trace(                go.Scatter(                    x=df_plot.columns,                    y=df_plot.loc[sample_id].to_numpy(),                    mode="lines",                    name=str(sample_id),                    line=dict(width=line_width),                    opacity=opacity,                    hovertemplate=(                        "Sample: %{fullData.name}<br>"                        "Wavenumber: %{x:.2f} cm⁻¹<br>"                        "Intensity: %{y:.3g}"                        "<extra></extra>"                    ),                )            )        legend_title = "Sample ID"    # ------------------------------------------------------------------    # Plot using metadata grouping    # ------------------------------------------------------------------    else:        if metadata is None:            raise ValueError(                "metadata must be provided when color_by is used."            )        if color_by not in metadata.columns:            raise KeyError(                f"'{color_by}' was not found in metadata."            )        missing_samples = df_plot.index.difference(metadata.index)        if len(missing_samples) > 0:            raise ValueError(                "Some samples in df are missing from metadata: "                f"{missing_samples.tolist()}"            )        groups = (            metadata.loc[df_plot.index, color_by]            .fillna("Unknown")            .astype(str)        )        unique_groups = groups.unique()        # Generate colors automatically        if color_map is None:            colors = (                qualitative.Plotly                + qualitative.Safe                + qualitative.Dark24            )            color_map = {                group: colors[i % len(colors)]                for i, group in enumerate(unique_groups)            }        legend_groups_added = set()        for sample_id in df_plot.index:            group = groups.loc[sample_id]            fig.add_trace(                go.Scatter(                    x=df_plot.columns,                    y=df_plot.loc[sample_id].to_numpy(),                    mode="lines",                    name=group,                    legendgroup=group,                    showlegend=(                        show_legend                        and group not in legend_groups_added                    ),                    line=dict(                        width=line_width,                        color=color_map[group],                    ),                    opacity=opacity,                    customdata=[str(sample_id)] * df_plot.shape[1],                    hovertemplate=(                        "Sample: %{customdata}<br>"                        f"{color_by}: {group}<br>"                        "Wavenumber: %{x:.2f} cm⁻¹<br>"                        "Intensity: %{y:.3g}"                        "<extra></extra>"                    ),                )            )            legend_groups_added.add(group)        legend_title = color_by    # ------------------------------------------------------------------    # Format the figure    # ------------------------------------------------------------------    fig.update_layout(        title=dict(            text=title,            x=0.5,            xanchor="center",        ),        xaxis_title=x_label,        yaxis_title=y_label,        template="simple_white",        hovermode="closest",        showlegend=show_legend,        legend_title_text=legend_title,        legend=dict(            groupclick="togglegroup",        ),        width=2500,        height=1100,        font=dict(            family="Arial",            size=16,        ),    )    fig.update_xaxes(        showline=True,        linewidth=1,        linecolor="black",        mirror=True,        ticks="outside",        autorange="reversed" if reverse_x else True,    )    fig.update_yaxes(        showline=True,        linewidth=1,        linecolor="black",        mirror=True,        ticks="outside",    )    return figdef plot_correlation_bubbles(    df,    figsize=(10, 8),    zero_threshold=0.0,    min_size=20,    max_size=480,    palette=None,    legend_values=(-1, -0.5, 0, 0.5, 1),    title=None,    correction_method="fdr_bh",    alpha=0.05,    annotate="strong",    annotation_r_threshold=0.90,    show_significance_stars=False,    bubble_axis_padding=0.50,    y_tick_padding=5,    annotation_fontsize=8,    star_fontsize=8,    ax=None,):    """    Plot the lower triangle of a Pearson correlation matrix as bubbles.    Bubble color represents the Pearson correlation coefficient.    Bubble size represents the absolute correlation strength.    For each variable pair, the function calculates:    - Pearson correlation coefficient, r    - raw p-value    - multiple-testing-adjusted p-value    - significance stars based on the adjusted p-value    Parameters    ----------    df : pandas.DataFrame        Input data with observations in rows and variables in columns.    figsize : tuple of float, default=(10, 8)        Figure width and height in inches.        This is used only when ax is None.    zero_threshold : float, default=0.0        Hide bubbles whose absolute correlation is less than or equal        to this value.        This controls which bubbles are displayed. It does not control        which bubbles are annotated.    min_size : float, default=20        Minimum bubble area in points squared.    max_size : float, default=480        Maximum bubble area in points squared.    palette : matplotlib colormap, str, or None, default=None        Colormap used for correlation coefficients.        When None, a custom blue-white-wine diverging colormap is used.    legend_values : sequence of float, default=(-1, -0.5, 0, 0.5, 1)        Correlation values shown in the combined color-and-size legend.    title : str or None, default=None        Optional title displayed above the plot.    correction_method : str, default="fdr_bh"        Multiple-testing correction passed to        statsmodels.stats.multitest.multipletests.        Common options:        - "fdr_bh": Benjamini-Hochberg FDR        - "bonferroni": Bonferroni correction        - "holm": Holm correction    alpha : float, default=0.05        Significance threshold for adjusted p-values.    annotate : {"none", "strong"}, default="strong"        Controls numerical annotations.        - "none": no correlation values are displayed        - "strong": display r for correlations satisfying          abs(r) >= annotation_r_threshold    annotation_r_threshold : float, default=0.90        Minimum absolute correlation required for annotation.        For example, 0.90 annotates correlations where:        - r >= 0.90        - r <= -0.90    show_significance_stars : bool, default=False        Add significance stars above annotated correlation values.        Stars are based on adjusted p-values:        - *   q < 0.05        - **  q < 0.01        - *** q < 0.001    bubble_axis_padding : float, default=0.70        Extra horizontal space added to the left side of the axes.        This prevents the first bubble column from overlapping the        y-axis metabolite labels, particularly in SVG files and        narrow subplot panels.        Increase this value for larger bubbles or narrow panels.    y_tick_padding : float, default=6        Distance in points between y-axis labels and the plot area.    annotation_fontsize : float, default=8        Font size of annotated correlation coefficients.    star_fontsize : float, default=8        Font size of significance stars.    ax : matplotlib.axes.Axes or None, default=None        Existing axes on which to draw the plot.        When None, a new figure and axes are created.    Returns    -------    fig : matplotlib.figure.Figure        Matplotlib figure object.    ax : matplotlib.axes.Axes        Matplotlib axes object.    corr_long : pandas.DataFrame        Long-format statistical results containing:        - variable_y        - variable_x        - correlation        - abs_correlation        - p_value        - p_fdr        - significant        - star        - n    Examples    --------    Create one standalone figure:    >>> fig, ax, corr_data = plot_correlation_bubbles(    ...     df,    ...     figsize=(10, 8),    ...     annotation_r_threshold=0.90,    ...     show_significance_stars=True,    ...     title="Mimicking with cottonseed oil",    ... )    >>> plt.show()    Increase spacing between labels and the first bubble column:    >>> fig, ax, corr_data = plot_correlation_bubbles(    ...     df,    ...     bubble_axis_padding=0.90,    ...     y_tick_padding=8,    ... )    >>> plt.show()    Use the function inside a subplot:    >>> fig, axs = plt.subplots(2, 2, figsize=(20, 18))    >>>    >>> plot_correlation_bubbles(    ...     df,    ...     ax=axs[0, 0],    ...     annotation_r_threshold=0.90,    ...     show_significance_stars=True,    ... )    >>>    >>> fig.tight_layout()    >>> plt.show()    Plot without annotations:    >>> fig, ax, corr_data = plot_correlation_bubbles(    ...     df,    ...     annotate="none",    ... )    >>> plt.show()    Inspect significant correlations:    >>> significant_results = (    ...     corr_data    ...     .query("significant == True")    ...     .sort_values("abs_correlation", ascending=False)    ... )    Save results:    >>> corr_data.to_excel(    ...     "correlation_results.xlsx",    ...     index=False,    ... )    """    # -------------------------------------------------------------------------    # Validate inputs    # -------------------------------------------------------------------------    if not isinstance(df, pd.DataFrame):        raise TypeError("df must be a pandas DataFrame.")    if not 0 <= zero_threshold <= 1:        raise ValueError("zero_threshold must be between 0 and 1.")    if not 0 < alpha < 1:        raise ValueError("alpha must be between 0 and 1.")    if not 0 <= annotation_r_threshold <= 1:        raise ValueError(            "annotation_r_threshold must be between 0 and 1."        )    if min_size <= 0:        raise ValueError("min_size must be greater than 0.")    if max_size <= min_size:        raise ValueError("max_size must be greater than min_size.")    if bubble_axis_padding < 0:        raise ValueError(            "bubble_axis_padding must be greater than or equal to 0."        )    if y_tick_padding < 0:        raise ValueError(            "y_tick_padding must be greater than or equal to 0."        )    if annotation_fontsize <= 0:        raise ValueError(            "annotation_fontsize must be greater than 0."        )    if star_fontsize <= 0:        raise ValueError(            "star_fontsize must be greater than 0."        )    valid_annotations = {"none", "strong"}    if annotate not in valid_annotations:        raise ValueError(            f"annotate must be one of {valid_annotations}."        )    if not isinstance(show_significance_stars, bool):        raise TypeError(            "show_significance_stars must be True or False."        )    # -------------------------------------------------------------------------    # Select numerical columns    # -------------------------------------------------------------------------    df_numeric = df.select_dtypes(include="number").copy()    if df_numeric.shape[1] < 2:        raise ValueError(            "The DataFrame must contain at least two numerical columns."        )    # Remove constant columns because Pearson correlation is undefined    constant_columns = df_numeric.columns[        df_numeric.nunique(dropna=True) <= 1    ].tolist()    if constant_columns:        df_numeric = df_numeric.drop(columns=constant_columns)    if df_numeric.shape[1] < 2:        raise ValueError(            "At least two non-constant numerical columns are required."        )    variables = df_numeric.columns.tolist()    # -------------------------------------------------------------------------    # Calculate Pearson r and raw p-values    # -------------------------------------------------------------------------    results = []    for i in range(1, len(variables)):        variable_y = variables[i]        for j in range(i):            variable_x = variables[j]            pair_data = df_numeric[                [variable_x, variable_y]            ].dropna()            n = len(pair_data)            if n < 3:                r_value = np.nan                p_value = np.nan            else:                try:                    r_value, p_value = pearsonr(                        pair_data[variable_x],                        pair_data[variable_y],                    )                except ValueError:                    r_value = np.nan                    p_value = np.nan            results.append(                {                    "variable_y": variable_y,                    "variable_x": variable_x,                    "correlation": r_value,                    "p_value": p_value,                    "n": n,                }            )    corr_long = pd.DataFrame(results)    # -------------------------------------------------------------------------    # Multiple-testing correction    # -------------------------------------------------------------------------    corr_long["p_fdr"] = np.nan    corr_long["significant"] = False    valid_p = corr_long["p_value"].notna()    if valid_p.any():        reject, p_adjusted, _, _ = multipletests(            corr_long.loc[valid_p, "p_value"],            alpha=alpha,            method=correction_method,        )        corr_long.loc[valid_p, "p_fdr"] = p_adjusted        corr_long.loc[valid_p, "significant"] = reject    # -------------------------------------------------------------------------    # Significance stars based on adjusted p-values    # -------------------------------------------------------------------------    def p_to_star(p_value):        if pd.isna(p_value):            return ""        if p_value < 0.001:            return "***"        if p_value < 0.01:            return "**"        if p_value < 0.05:            return "*"        return ""    corr_long["star"] = corr_long["p_fdr"].apply(p_to_star)    corr_long["abs_correlation"] = corr_long["correlation"].abs()    # -------------------------------------------------------------------------    # Apply bubble-display threshold    # -------------------------------------------------------------------------    corr_plot = corr_long.loc[        corr_long["abs_correlation"] > zero_threshold    ].copy()    if corr_plot.empty:        raise ValueError(            "No correlations remain after applying zero_threshold."        )    # -------------------------------------------------------------------------    # Preserve original variable order    # -------------------------------------------------------------------------    for column in ["variable_x", "variable_y"]:        corr_plot[column] = pd.Categorical(            corr_plot[column],            categories=variables,            ordered=True,        )    # -------------------------------------------------------------------------    # Format numerical annotations    # -------------------------------------------------------------------------    def format_correlation(value):        """        Convert:        0.98  -> .98        -0.92 -> -.92        1.00  -> 1.00        -1.00 -> -1.00        """        formatted = f"{value:.2f}"        if formatted.startswith("-0"):            return "-" + formatted[2:]        if formatted.startswith("0"):            return formatted[1:]        return formatted    corr_plot["annotation"] = ""    if annotate == "strong":        strong_mask = (            corr_plot["abs_correlation"]            >= annotation_r_threshold        )        corr_plot.loc[            strong_mask,            "annotation",        ] = corr_plot.loc[            strong_mask,            "correlation",        ].apply(format_correlation)    # -------------------------------------------------------------------------    # Create colormap    # -------------------------------------------------------------------------    if palette is None:        palette = LinearSegmentedColormap.from_list(            "foodomics_correlation",            [                "#3F6F9F",                "#94AEC8",                "#DDE4EA",                "#F7F7F7",                "#E9C5C0",                "#CB746B",                "#9C2113",            ],        )    elif isinstance(palette, str):        palette = plt.get_cmap(palette)    norm = Normalize(vmin=-1, vmax=1)    # -------------------------------------------------------------------------    # Plot    # -------------------------------------------------------------------------    created_new_axes = ax is None    with sns.axes_style("whitegrid"):        if created_new_axes:            fig, ax = plt.subplots(figsize=figsize)        else:            fig = ax.figure        sns.scatterplot(            data=corr_plot,            x="variable_x",            y="variable_y",            hue="correlation",            size="abs_correlation",            palette=palette,            hue_norm=(-1, 1),            sizes=(min_size, max_size),            size_norm=(0, 1),            marker="o",            edgecolor="#C9C9C9",            linewidth=0.75,            clip_on=True,            legend=False,            ax=ax,        )        # ---------------------------------------------------------------------        # Add extra space between labels and the first bubble column        # ---------------------------------------------------------------------        n_variables = len(variables)        ax.set_xlim(            -0.5 - bubble_axis_padding,            n_variables - 0.5,        )        # ---------------------------------------------------------------------        # Add white correlation values and optional stars        # ---------------------------------------------------------------------        for _, row in corr_plot.iterrows():            if row["annotation"] == "":                continue            # Correlation coefficient slightly below the bubble center            ax.annotate(                row["annotation"],                xy=(row["variable_x"], row["variable_y"]),                xytext=(0, -2),                textcoords="offset points",                ha="center",                va="center",                fontsize=annotation_fontsize,                fontweight="bold",                color="white",                clip_on=True,            )            # Significance stars slightly above the coefficient            if show_significance_stars and row["star"]:                ax.annotate(                    row["star"],                    xy=(row["variable_x"], row["variable_y"]),                    xytext=(0, 3),                    textcoords="offset points",                    ha="center",                    va="center",                    fontsize=star_fontsize,                    fontweight="bold",                    color="white",                    clip_on=True,                )        # ---------------------------------------------------------------------        # Axis formatting        # ---------------------------------------------------------------------        ax.set_xlabel("")        ax.set_ylabel("")        ax.set_aspect("equal", adjustable="box")        ax.tick_params(            axis="x",            labelrotation=90,            labelsize=10,            length=0,        )        ax.tick_params(            axis="y",            labelsize=10,            length=0,            pad=y_tick_padding,        )        ax.grid(            visible=True,            color="#E5E5E5",            linewidth=0.65,        )        ax.set_axisbelow(True)        sns.despine(            ax=ax,            left=True,            bottom=True,        )        if title is not None:            ax.set_title(                title,                fontsize=13,                pad=14,            )        # ---------------------------------------------------------------------        # Combined color-and-size legend        # ---------------------------------------------------------------------        legend_handles = []        for value in legend_values:            if not -1 <= value <= 1:                raise ValueError(                    "All legend_values must be between -1 and 1."                )            bubble_area = (                min_size                + abs(value) * (max_size - min_size)            )            marker_size = np.sqrt(bubble_area)            legend_handles.append(                Line2D(                    [],                    [],                    linestyle="",                    marker="o",                    markersize=marker_size,                    markerfacecolor=palette(norm(value)),                    markeredgecolor="#C9C9C9",                    markeredgewidth=0.75,                    label=f"{value:.1f}",                )            )        correlation_legend = ax.legend(            handles=legend_handles,            title="",            frameon=False,            loc="upper left",            bbox_to_anchor=(1.02, 1.00),            borderaxespad=0,            labelspacing=1.5,            handletextpad=1.0,        )        ax.add_artist(correlation_legend)        # ---------------------------------------------------------------------        # Optional significance explanation        # ---------------------------------------------------------------------        if show_significance_stars:            ax.text(                1.02,                0.55,                "FDR significance\n"                "*   q < 0.05\n"                "**  q < 0.01\n"                "*** q < 0.001",                transform=ax.transAxes,                ha="left",                va="top",                fontsize=9,            )    # Apply tight layout only when this function created the figure    if created_new_axes:        fig.tight_layout()    return fig, ax, corr_longdef save_figure(    fig,    path,    width=1200,    height=700,    scale=2,):    """    Save a Plotly figure.    Parameters    ----------    fig : plotly.graph_objects.Figure        Plotly figure to save.    path : str or pathlib.Path        Output filename. The file extension determines        the output format (.html, .png, .svg, .pdf).    width : int, default=1200        Width in pixels for static images.    height : int, default=700        Height in pixels for static images.    scale : float, default=2        Image scaling factor for static images.    Returns    -------    pathlib.Path        Path to the saved figure.    Examples    --------    >>> save_figure(fig, "figure.html")    >>> save_figure(fig, "figure.png")    >>> save_figure(fig, "figure.svg")    """    path = Path(path)    path.parent.mkdir(        parents=True,        exist_ok=True,    )    suffix = path.suffix.lower()    if suffix == ".html":        fig.write_html(path)    elif suffix in {        ".png",        ".svg",        ".pdf",        ".jpg",        ".jpeg",        ".webp",    }:        fig.write_image(            path,            width=width,            height=height,            scale=scale,        )    else:        raise ValueError(            f"Unsupported file format: '{suffix}'.\n"            "Supported formats are:\n"            ".html, .png, .svg, .pdf, .jpg, .jpeg, .webp"        )    return pathdef plot_pls(    result,    figsize=(15, 4.7),    point_size=55,    point_alpha=0.85,    show_calibration=False,    show_regression_line=False,    show_sample_labels=False,    label_residual_threshold=None,    title=None,    save_path=None,    dpi=600,):    """    Create publication-ready diagnostic plots for a PLS regression model.    The figure contains three panels:        A. RMSECV versus number of PLS components        B. Measured versus cross-validated predicted values        C. Cross-validated residuals versus predicted values    Parameters    ----------    result : dict        Result dictionary returned by perform_pls().        The dictionary must contain:            "component_results"            "n_components"            "y_measured"            "y_cv_predicted"            "residuals_cv"            "rmsecv"            "r2cv"        Optional entries used when available:            "y_calibration_predicted"            "rmsec"            "r2c"            "maecv"            "bias_cv"            "prediction_slope"            "prediction_intercept"            "sample_names"            "y_name"    figsize : tuple, default=(15, 4.7)        Overall figure size.    point_size : float, default=55        Scatter-point size.    point_alpha : float, default=0.85        Scatter-point transparency.    show_calibration : bool, default=False        Show calibration predictions in the measured-versus-predicted        panel in addition to cross-validation predictions.        Cross-validation predictions remain the primary result.    show_regression_line : bool, default=False        Add a fitted regression line to the measured-versus-predicted        panel.        The identity line is always displayed.    show_sample_labels : bool, default=False        Label all observations using result["sample_names"].        For large datasets, it is usually better to leave this False.    label_residual_threshold : float or None, default=None        Label only samples whose absolute cross-validation residual is        greater than or equal to this threshold.        For example:            label_residual_threshold=2.5    title : str or None, default=None        Optional overall figure title.    save_path : str, pathlib.Path, or None, default=None        Optional output path.        Supported extensions include:            .png            .svg            .pdf            .tiff        Example:            save_path="figures/pls_diagnostics.svg"    dpi : int, default=600        Resolution used for raster output.    Returns    -------    fig : matplotlib.figure.Figure        Matplotlib figure.    axes : numpy.ndarray of matplotlib.axes.Axes        Array containing the three axes.    Examples    --------    >>> fig, axes = plot_pls(result)    >>> fig, axes = plot_pls(    ...     result,    ...     title="PLS model for moisture prediction",    ...     save_path="PLS_moisture.svg",    ... )    >>> fig, axes = plot_pls(    ...     result,    ...     label_residual_threshold=2.5,    ... )    """    # ==================================================================    # 1. VALIDATE INPUT    # ==================================================================    if not isinstance(result, dict):        raise TypeError(            "'result' must be the dictionary returned by perform_pls()."        )    required_keys = {        "component_results",        "n_components",        "y_measured",        "y_cv_predicted",        "residuals_cv",        "rmsecv",        "r2cv",    }    missing_keys = required_keys.difference(result)    if missing_keys:        raise KeyError(            "The PLS result is missing the following required entries: "            f"{sorted(missing_keys)}"        )    component_results = result["component_results"].copy()    required_component_columns = {        "n_components",        "rmsecv",    }    missing_columns = required_component_columns.difference(        component_results.columns    )    if missing_columns:        raise KeyError(            "result['component_results'] is missing the following "            f"columns: {sorted(missing_columns)}"        )    y_measured = np.asarray(        result["y_measured"],        dtype=float,    ).reshape(-1)    y_cv_predicted = np.asarray(        result["y_cv_predicted"],        dtype=float,    ).reshape(-1)    residuals_cv = np.asarray(        result["residuals_cv"],        dtype=float,    ).reshape(-1)    if not (        len(y_measured)        == len(y_cv_predicted)        == len(residuals_cv)    ):        raise ValueError(            "Measured values, CV predictions, and CV residuals must "            "have the same length."        )    n_samples = len(y_measured)    sample_names = result.get(        "sample_names",        np.arange(1, n_samples + 1),    )    sample_names = np.asarray(sample_names).reshape(-1)    if len(sample_names) != n_samples:        sample_names = np.arange(1, n_samples + 1)    best_n_components = int(result["n_components"])    rmsecv = float(result["rmsecv"])    r2cv = float(result["r2cv"])    maecv = result.get("maecv")    bias_cv = result.get("bias_cv")    y_name = result.get("y_name")    if y_name is None:        y_name = "Response"    # ==================================================================    # 2. COLORS    # ==================================================================    color_primary = "#246B73"    color_secondary = "#D58A35"    color_dark = "#222222"    color_grey = "#777777"    color_light_grey = "#D9D9D9"    color_grid = "#E8E8E8"    color_residual = "#A34545"    color_calibration = "#9A9A9A"    # ==================================================================    # 3. MATPLOTLIB SETTINGS    # ==================================================================    plot_settings = {        "font.family": "sans-serif",        "font.sans-serif": [            "Arial",            "Helvetica",            "DejaVu Sans",        ],        "font.size": 10,        "axes.labelsize": 11,        "axes.titlesize": 12,        "axes.titleweight": "bold",        "xtick.labelsize": 9,        "ytick.labelsize": 9,        "legend.fontsize": 9,        "axes.linewidth": 0.9,        "svg.fonttype": "none",        "pdf.fonttype": 42,        "ps.fonttype": 42,    }    with plt.rc_context(plot_settings):        # ==============================================================        # 4. CREATE FIGURE        # ==============================================================        fig, axes = plt.subplots(            nrows=1,            ncols=3,            figsize=figsize,            constrained_layout=False,        )        ax_components = axes[0]        ax_predictions = axes[1]        ax_residuals = axes[2]        # ==============================================================        # 5. PANEL A — COMPONENT SELECTION        # ==============================================================        n_components = component_results[            "n_components"        ].to_numpy()        rmsecv_values = component_results[            "rmsecv"        ].to_numpy()        ax_components.plot(            n_components,            rmsecv_values,            color=color_primary,            linewidth=2.0,            marker="o",            markersize=5.5,            markerfacecolor="white",            markeredgecolor=color_primary,            markeredgewidth=1.4,            zorder=3,        )        selected_row = component_results.loc[            component_results["n_components"]            == best_n_components        ]        if selected_row.empty:            best_rmsecv = rmsecv        else:            best_rmsecv = float(                selected_row["rmsecv"].iloc[0]            )        ax_components.scatter(            best_n_components,            best_rmsecv,            s=105,            color=color_secondary,            edgecolor="white",            linewidth=1.5,            zorder=5,            label=(                f"Selected: {best_n_components} components"            ),        )        ax_components.axvline(            best_n_components,            color=color_secondary,            linewidth=1.0,            linestyle=(0, (4, 3)),            alpha=0.8,            zorder=1,        )        ax_components.annotate(            (                f"{best_n_components} components\n"                f"RMSECV = {best_rmsecv:.3f}"            ),            xy=(best_n_components, best_rmsecv),            xytext=(10, 18),            textcoords="offset points",            fontsize=9,            color=color_dark,            ha="left",            va="bottom",            bbox={                "boxstyle": "round,pad=0.35",                "facecolor": "white",                "edgecolor": color_light_grey,                "linewidth": 0.8,                "alpha": 0.95,            },            arrowprops={                "arrowstyle": "-",                "color": color_grey,                "linewidth": 0.8,            },        )        ax_components.set_xlabel(            "Number of PLS components"        )        ax_components.set_ylabel("RMSECV")        ax_components.set_title(            "Model complexity",            loc="left",            pad=12,        )        ax_components.xaxis.set_major_locator(            MaxNLocator(integer=True)        )        # ==============================================================        # 6. PANEL B — MEASURED VS PREDICTED        # ==============================================================        combined_values = np.concatenate(            [y_measured, y_cv_predicted]        )        if show_calibration:            if "y_calibration_predicted" not in result:                raise KeyError(                    "show_calibration=True requires "                    "result['y_calibration_predicted']."                )            y_calibration_predicted = np.asarray(                result["y_calibration_predicted"],                dtype=float,            ).reshape(-1)            combined_values = np.concatenate(                [                    combined_values,                    y_calibration_predicted,                ]            )            ax_predictions.scatter(                y_measured,                y_calibration_predicted,                s=point_size * 0.8,                color=color_calibration,                edgecolor="white",                linewidth=0.7,                alpha=0.50,                label="Calibration",                zorder=2,            )        value_min = np.nanmin(combined_values)        value_max = np.nanmax(combined_values)        value_range = value_max - value_min        if np.isclose(value_range, 0):            value_range = 1.0        padding = value_range * 0.07        plot_min = value_min - padding        plot_max = value_max + padding        ax_predictions.plot(            [plot_min, plot_max],            [plot_min, plot_max],            color=color_dark,            linewidth=1.2,            linestyle=(0, (5, 4)),            label="Identity line",            zorder=1,        )        ax_predictions.scatter(            y_measured,            y_cv_predicted,            s=point_size,            color=color_primary,            edgecolor="white",            linewidth=0.9,            alpha=point_alpha,            label="Cross-validation",            zorder=3,        )        if show_regression_line:            slope, intercept = np.polyfit(                y_measured,                y_cv_predicted,                deg=1,            )            regression_x = np.array(                [plot_min, plot_max]            )            regression_y = (                slope * regression_x + intercept            )            ax_predictions.plot(                regression_x,                regression_y,                color=color_secondary,                linewidth=1.8,                label="Fitted line",                zorder=2,            )        metric_lines = [            rf"$R^2_{{CV}}$ = {r2cv:.3f}",            f"RMSECV = {rmsecv:.3f}",        ]        if maecv is not None:            metric_lines.append(                f"MAECV = {float(maecv):.3f}"            )        if bias_cv is not None:            metric_lines.append(                f"Bias = {float(bias_cv):.3f}"            )        ax_predictions.text(            0.05,            0.95,            "\n".join(metric_lines),            transform=ax_predictions.transAxes,            ha="left",            va="top",            fontsize=9.5,            linespacing=1.35,            bbox={                "boxstyle": "round,pad=0.45",                "facecolor": "white",                "edgecolor": "white",                "linewidth": 0.8,                "alpha": 0.95,            },            zorder=10,        )        ax_predictions.set_xlim(plot_min, plot_max)        ax_predictions.set_ylim(plot_min, plot_max)        ax_predictions.set_aspect(            "equal",            adjustable="box",        )        ax_predictions.set_xlabel(            f"Measured {y_name}"        )        ax_predictions.set_ylabel(            f"Cross-validated predicted {y_name}"        )        ax_predictions.set_title(            "Prediction performance",            loc="left",            pad=12,        )        # ==============================================================        # 7. PANEL C — RESIDUALS        # ==============================================================        ax_residuals.axhline(            0,            color=color_dark,            linewidth=1.1,            linestyle=(0, (5, 4)),            zorder=1,        )        ax_residuals.scatter(            y_cv_predicted,            residuals_cv,            s=point_size,            color=color_residual,            edgecolor="white",            linewidth=0.9,            alpha=point_alpha,            zorder=3,        )        residual_sd = np.std(            residuals_cv,            ddof=1,        )        if np.isfinite(residual_sd) and residual_sd > 0:            ax_residuals.axhline(                2 * residual_sd,                color=color_grey,                linewidth=0.9,                linestyle=(0, (2, 3)),                alpha=0.75,                zorder=1,            )            ax_residuals.axhline(                -2 * residual_sd,                color=color_grey,                linewidth=0.9,                linestyle=(0, (2, 3)),                alpha=0.75,                zorder=1,            )            ax_residuals.text(                0.98,                2 * residual_sd,                "+2 SD ",                transform=ax_residuals.get_yaxis_transform(),                ha="right",                va="bottom",                fontsize=8,                color=color_grey,            )            ax_residuals.text(                0.98,                -2 * residual_sd,                "−2 SD ",                transform=ax_residuals.get_yaxis_transform(),                ha="right",                va="top",                fontsize=8,                color=color_grey,            )        ax_residuals.set_xlabel(            f"Cross-validated predicted {y_name}"        )        ax_residuals.set_ylabel(            "Residual (measured − predicted)"        )        ax_residuals.set_title(            "Residual diagnostics",            loc="left",            pad=12,        )        # ==============================================================        # 8. SAMPLE LABELS        # ==============================================================        if show_sample_labels:            label_mask = np.ones(                n_samples,                dtype=bool,            )        elif label_residual_threshold is not None:            if label_residual_threshold < 0:                raise ValueError(                    "'label_residual_threshold' must be "                    "greater than or equal to zero."                )            label_mask = (                np.abs(residuals_cv)                >= label_residual_threshold            )        else:            label_mask = np.zeros(                n_samples,                dtype=bool,            )        for index in np.where(label_mask)[0]:            label = str(sample_names[index])            ax_predictions.annotate(                label,                (                    y_measured[index],                    y_cv_predicted[index],                ),                xytext=(4, 4),                textcoords="offset points",                fontsize=7.5,                color=color_dark,                alpha=0.9,            )            ax_residuals.annotate(                label,                (                    y_cv_predicted[index],                    residuals_cv[index],                ),                xytext=(4, 4),                textcoords="offset points",                fontsize=7.5,                color=color_dark,                alpha=0.9,            )        # ==============================================================        # 9. COMMON STYLE        # ==============================================================        panel_labels = ["A", "B", "C"]        for ax, panel_label in zip(            axes,            panel_labels,        ):            ax.text(                -0.15,                1.08,                panel_label,                transform=ax.transAxes,                fontsize=14,                fontweight="bold",                ha="left",                va="top",                color=color_dark,            )            ax.spines["top"].set_visible(False)            ax.spines["right"].set_visible(False)            ax.spines["left"].set_color(                color_dark            )            ax.spines["bottom"].set_color(                color_dark            )            ax.tick_params(                axis="both",                direction="out",                length=4,                width=0.8,                color=color_dark,            )            ax.grid(                True,                axis="both",                color=color_grid,                linewidth=0.7,                alpha=0.65,                zorder=0,            )            ax.set_axisbelow(True)        # ==============================================================        # 10. OPTIONAL OVERALL TITLE        # ==============================================================        if title is not None:            fig.suptitle(                title,                fontsize=15,                fontweight="bold",                x=0.06,                ha="left",                y=1.02,            )        # ==============================================================        # 11. SPACING        # ==============================================================        fig.subplots_adjust(            left=0.065,            right=0.985,            bottom=0.17,            top=0.86 if title is None else 0.81,            wspace=0.35,        )        # ==============================================================        # 12. SAVE        # ==============================================================        if save_path is not None:            save_path = Path(save_path)            save_path.parent.mkdir(                parents=True,                exist_ok=True,            )            if save_path.suffix == "":                save_path = save_path.with_suffix(                    ".png"                )            fig.savefig(                save_path,                dpi=dpi,                bbox_inches="tight",                facecolor="white",            )    return fig, axes